168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        HttpHeaders headers = new HttpHeaders();
176	        Pet pet = petMapper.toPet(petFieldsDto);
177	        owner.setId(ownerId);
178	        pet.setOwner(owner);
179	        pet.getType().setName(null);
180	        this.clinicService.savePet(pet);
181	        PetDto petDto = petMapper.toPetDto(pet);
182	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
183	            .buildAndExpand(pet.getId()).toUri());
184	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner != null) {
192	            Pet currentPet = this.clinicService.findPetById(petId);
193	            if (currentPet != null) {
194	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
195	                currentPet.setName(petFieldsDto.getName());
196	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
197	                this.clinicService.savePet(currentPet);
198	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
199	            }
200	        }
201	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
207	        HttpHeaders headers = new HttpHeaders();
208	        Visit visit = visitMapper.toVisit(visitFieldsDto);
209	        Pet pet = new Pet();
210	        pet.setId(petId);
211	        visit.setPet(pet);
212	        this.clinicService.saveVisit(visit);
213	        VisitDto visitDto = visitMapper.toVisitDto(visit);
214	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
215	            .buildAndExpand(visit.getId()).toUri());
216	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
217	    }
218	
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner != null) {
225	            Pet pet = owner.getPet(petId);
226	            if (pet != null) {
227	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
228	            }
229	        }
230	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	    }
232	
233	    /**
234	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
235	     * the canonical form each stored value must take: the address is trimmed,
236	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
237	     * telephone is converted to E.164, any email is lower-cased and a missing
238	     * registration date defaults to today. Field-level rejections are reported here
239	     * rather than inline in {@link #addOwner}, and normalisation runs before any
240	     * household comparison so those comparisons see the canonical values.
241	     *
242	     * @param owner the freshly-mapped owner to normalise
243	     * @return {@code true} if the fields are valid, or {@code false} if the address
244	     *         is blank after normalisation, the telephone cannot form a valid
245	     *         E.164 number, or a supplied registration date is later than the
246	     *         server date, in which case the request must be rejected with
247	     *         {@code 400 Bad Request}
248	     */
249	    private boolean normalizeNewOwner(Owner owner) {
250	        String address = Owner.normalizeAddress(owner.getAddress());
251	        if (address.isEmpty()) {
252	            return false;
253	        }
254	        owner.setAddress(address);
255	        String telephone = Telephones.toE164(owner.getTelephone());
256	        if (telephone == null) {
257	            return false;
258	        }
259	        owner.setTelephone(telephone);
260	        if (owner.getEmail() != null) {
261	            String email = owner.getEmail().toLowerCase();
262	            owner.setEmail(email);
263	            if (emailDomainIsBlocked(email)) {
264	                return false;
265	            }
266	        }
267	        if (!owner.postcodeValidForLocality()) {
268	            return false;
269	        }
270	        if (owner.getRegistrationDate() == null) {
271	            owner.setRegistrationDate(LocalDate.now());
272	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
273	            return false;
274	        }
275	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
276	        return true;
277	    }
278	
279	    /**
280	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
281	     * email address is on one of these domains is rejected with {@code 400 Bad
282	     * Request} rather than created.
283	     */
284	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
285	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
286	
287	    /**
288	     * Whether the given (already lower-cased) email address belongs to a disposable
289	     * mailbox domain on the blocklist. The domain is the part after the final
290	     * {@code '@'}; an address without one is treated as having no blocked domain.
291	     *
292	     * @param email the owner's normalised (lower-cased) email address
293	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
294	     */
295	    private static boolean emailDomainIsBlocked(String email) {
296	        int at = email.lastIndexOf('@');
297	        if (at < 0) {
298	            return false;
299	        }
300	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
301	    }
302	
303	    /**
304	     * Roll the given date forward to the next business day when it falls on a
305	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
306	     * weekday is returned unchanged. Applied to the effective registration date
307	     * (whether supplied in the request or defaulted to the server date) so that
308	     * every value derived from it uses the adjusted business day.
309	     *
310	     * @param date the effective registration date
311	     * @return the same date if it is a weekday, otherwise the next Monday
312	     */
313	    private static LocalDate rollToBusinessDay(LocalDate date) {
314	        switch (date.getDayOfWeek()) {
315	            case SATURDAY:
316	                return date.plusDays(2);
317	            case SUNDAY:
318	                return date.plusDays(1);
319	            default:
320	                return date;
321	        }
322	    }
323	
324	    /**
325	     * Find an existing owner that belongs to the same household as the given owner,
326	     * i.e. shares the same last name (compared case-insensitively with runs of
327	     * whitespace collapsed to a single space) and postcode, and so resolves to the same
328	     * deterministic {@code householdId}.
329	     *
330	     * @param owner the candidate owner being created
331	     * @return the matching existing owner, or empty if none exists
332	     */
333	    private Optional<Owner> findHouseholdMember(Owner owner) {
334	        return this.clinicService.findAllOwners().stream()
335	            .filter(existing -> existing.sameHouseholdAs(owner))
336	            .findFirst();
337	    }
338	
339	    /**
340	     * Assign the owner's computed-at-creation attributes in place: its customer code,
341	     * namesake count, membership number, bulk-signup warning and household size. Unlike
342	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
343	     * derived once here — from the owner's own (already normalised) fields and from the
344	     * wider owner population — and persisted with the owner. Run after normalisation,
345	     * household resolution and the identity-key check, so every value reflects the
346	     * owner's final field values and any household it has joined, and immediately before
347	     * the owner is saved.
348	     *
349	     * <p>Ordering matters: the customer code is assigned first because the membership
350	     * number is built from it.
351	     *
352	     * @param owner the candidate owner being created, after household resolution
353	     * @param declaredHouseholdMember whether this owner was created as a declared member
354	     *                                of an existing household (it shared an existing
355	     *                                owner's household and set {@code sharesHousehold}),
356	     *                                in which case it is not a suspected duplicate
357	     */
358	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember) {
359	        owner.setCustomerCode(deduplicatedCustomerCode(owner));
360	        owner.setNamesakeCount(countNamesakes(owner));
361	        owner.setMembershipNumber(membershipNumber(owner));
362	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
363	        owner.setHouseholdSize(householdSize(owner));
364	        assignPossibleDuplicate(owner, declaredHouseholdMember);
365	    }
366	
367	    /**
368	     * Compute the customer code to assign to the candidate owner, de-duplicated against
369	     * every existing owner's customer code. The base code is the owner's computed
370	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
371	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
372	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
373	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
374	     * before the owner is saved, so only pre-existing owners are considered.
375	     *
376	     * @param owner the candidate owner being created, after normalisation
377	     * @return the unique (de-duplicated) customer code to assign
378	     */
379	    private String deduplicatedCustomerCode(Owner owner) {
380	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
381	            .map(Owner::getCustomerCode)
382	            .filter(code -> code != null)
383	            .collect(java.util.stream.Collectors.toSet());
384	        String base = owner.computeCustomerCode();
385	        if (!existingCodes.contains(base)) {
386	            return base;
387	        }
388	        int n = 2;
389	        while (existingCodes.contains(base + "-" + n)) {
390	            n++;
391	        }
392	        return base + "-" + n;
393	    }
394	
395	    /**
396	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
397	     * match is an existing owner that shares this owner's last name (compared
398	     * case-insensitively) and postcode but carries a different (normalised) telephone.
399	     * When such a match exists the owner is still created, but with
400	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
401	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
402	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
403	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
404	     * are considered.
405	     *
406	     * <p>A declared household member — one that shared an existing owner's household
407	     * (same last name and postcode) and was admitted because it set
408	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
409	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
410	     *
411	     * @param owner the candidate owner being created, after household resolution
412	     * @param declaredHouseholdMember whether the owner is a declared household member
413	     */
414	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
415	        if (declaredHouseholdMember) {
416	            owner.setPossibleDuplicate(false);
417	            owner.setPossibleDuplicateOf(null);
418	            return;
419	        }
420	        String lastName = normalizeName(owner.getLastName());
421	        String postcode = owner.getPostcode();
422	        String telephone = owner.getTelephone();
423	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
424	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
425	                && normalizeName(existing.getLastName()).equals(lastName)
426	                && telephone != null && !telephone.equals(existing.getTelephone()))
427	            .min(Comparator.comparing(Owner::getId));
428	        if (match.isPresent()) {
429	            owner.setPossibleDuplicate(true);
430	            owner.setPossibleDuplicateOf(match.get().getId());
431	        } else {
432	            owner.setPossibleDuplicate(false);
433	            owner.setPossibleDuplicateOf(null);
434	        }
435	    }
436	
437	    /**
438	     * Count how many owners belong to the given owner's household once this create
439	     * completes: the owners that already share its deterministic {@code householdId}
440	     * (derived from last name and postcode) plus the owner being created. Evaluated
441	     * after the owner's {@code householdId} has been assigned. An owner whose
442	     * {@code householdId} matches no existing owner is a household of one.
443	     *
444	     * @param owner the candidate owner being created, after household resolution
445	     * @return the household member count after this create (at least {@code 1})
446	     */
447	    private int householdSize(Owner owner) {
448	        String householdId = owner.getHouseholdId();
449	        if (householdId == null) {
450	            return 1;
451	        }
452	        long existing = this.clinicService.findAllOwners().stream()
453	            .filter(other -> householdId.equals(other.getHouseholdId()))
454	            .count();
455	        return (int) existing + 1;
456	    }
457	
458	    /**
459	     * Count the existing owners that share the given owner's first and last name,
460	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
461	     * before the new owner is saved, so the result reflects only owners that
462	     * already existed at creation time.
463	     *
464	     * @param owner the candidate owner being created
465	     * @return the number of existing namesakes
466	     */
467	    private int countNamesakes(Owner owner) {
468	        String firstName = normalizeName(owner.getFirstName());
469	        String lastName = normalizeName(owner.getLastName());
470	        return (int) this.clinicService.findAllOwners().stream()
471	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
472	                && normalizeName(existing.getLastName()).equals(lastName))
473	            .count();
474	    }
475	
476	    private static String normalizeName(String value) {
477	        return value == null ? "" : value.trim().toLowerCase();
478	    }
479	
480	    /**
481	     * Determine whether the given city has already reached its owner capacity, i.e.
482	     * it already contains 50 or more existing owners (compared case-insensitively
483	     * with surrounding whitespace trimmed). A new owner may not be created in a city
484	     * that is at capacity.
485	     *
486	     * @param city the candidate owner's city
487	     * @return {@code true} if the city already holds 50 or more owners
488	     */
489	    private boolean cityIsAtCapacity(String city) {
490	        String normalizedCity = normalizeName(city);
491	        long count = this.clinicService.findAllOwners().stream()
492	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
493	            .count();
494	        return count >= 50;
495	    }
496	
497	    /**
498	     * Determine whether the daily owner-creation limit has already been reached, i.e.
499	     * 100 or more owners already carry the given registration date. A new owner may
500	     * not be created once that day's cap is reached.
501	     *
502	     * @param registrationDate the registration date the new owner would be created with
503	     * @return {@code true} if 100 or more existing owners share that registration date
504	     */
505	    private boolean dailyLimitReached(LocalDate registrationDate) {
506	        long count = this.clinicService.findAllOwners().stream()
507	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
508	            .count();
509	        return count >= 100;
510	    }
511	
512	    /**
513	     * Determine whether more than 80 owners have already been created for the given
514	     * registration date, i.e. strictly more than 80 existing owners carry that date.
515	     * Evaluated before the new owner is saved, so it reflects only owners that
516	     * already existed at creation time.
517	     *
518	     * @param registrationDate the registration date the new owner would be created with
519	     * @return {@code true} if more than 80 existing owners share that registration date
520	     */
521	    private boolean bulkSignupWarning(LocalDate registrationDate) {
522	        long count = this.clinicService.findAllOwners().stream()
523	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
524	            .count();
525	        return count > 80;
526	    }
527	
528	    /**
529	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
530	     * one place so it stays in step with the owner's identity: it reports the assigned
531	     * customer code alongside the owner's id, registration date, membership level and
532	     * membership number.
533	     *
534	     * @param owner the owner that has just been created and saved
535	     */
536	    private void auditOwnerCreated(Owner owner) {
537	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
538	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
539	            owner.getMembershipNumber());
540	    }
541	
542	    /**
543	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
544	     * where {@code <customerCode>} is the owner's already-assigned customer code and
545	     * YY is the last two digits of the registration date's year (e.g.
546	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
547	     * have been set.
548	     *
549	     * @param owner the owner being created, with customer code and registration date
550	     *              already assigned
551	     * @return the assigned membership number
552	     */
553	    private String membershipNumber(Owner owner) {
554	        int yy = owner.getRegistrationDate().getYear() % 100;
