74	
75	    @Column(name = "membership_number")
76	    private String membershipNumber;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "possible_duplicate")
85	    private Boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public String getAddress() {
94	        return this.address;
95	    }
96	
97	    public void setAddress(String address) {
98	        this.address = address;
