409	    /**
410	     * Reduce an address to its canonical stored form: trim and collapse runs of
411	     * whitespace to a single space, upper-case, and expand common abbreviations
412	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
413	     * they appear as whole words. The result is what is stored, returned and used
414	     * for every household comparison; it is idempotent, so re-normalising an
415	     * already-normalised address leaves it unchanged.
416	     *
417	     * @param value the raw address (may be {@code null})
418	     * @return the normalised address, or the empty string if {@code value} is
419	     *         {@code null} or blank
420	     */
421	    public static String normalizeAddress(String value) {
422	        if (value == null) {
423	            return "";
424	        }
425	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
426	        if (collapsed.isEmpty()) {
427	            return "";
428	        }
429	        String[] tokens = collapsed.split(" ");
430	        for (int i = 0; i < tokens.length; i++) {
431	            tokens[i] = switch (tokens[i]) {
432	                case "ST" -> "STREET";
433	                case "RD" -> "ROAD";
434	                case "AVE" -> "AVENUE";
435	                default -> tokens[i];
436	            };
437	        }
438	        return String.join(" ", tokens);
439	    }
