    }

    public Boolean getPossibleDuplicate() {
        return this.possibleDuplicate;
    }

    public void setPossibleDuplicate(Boolean possibleDuplicate) {
        this.possibleDuplicate = possibleDuplicate;
    }

    public Integer getPossibleDuplicateOf() {
        return this.possibleDuplicateOf;
    }

    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
        this.possibleDuplicateOf = possibleDuplicateOf;
    }

    /**
     * The derived key used for duplicate detection, combining this owner's normalised
     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
     * their whole identity keys are equal, so members of the same household with
     * different telephones have different keys. Derived (not persisted); recomputed each
     * call. See {@link OwnerDerivations#identityKey(String, String, String)} for the
     * exact format.
     *
     * @return the owner's identity key
     */
    @Transient
    public String getIdentityKey() {
        return OwnerDerivations.identityKey(this.telephone, this.email, this.householdId);
    }

    /**
     * Compute the customer code to assign to this owner at creation, formatted
     * {@code <REGION>-<HASH8>} from the owner's (already normalised) fields. This is the
     * value stored in {@link #getCustomerCode()}; see
     * {@link OwnerDerivations#customerCode(String, String, String)} for the format.
     *
     * @return the customer code to assign
     */
    public String computeCustomerCode() {
        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
    }

    /**
     * Compute the stable household identifier for this owner, derived deterministically
     * from its last name and postcode so every owner sharing a last name and postcode
     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
     *
     * @return the household identifier
     */
    public String computeHouseholdId() {
        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
    }

    /**
     * Whether this owner belongs to the same household as {@code other}: that is, they
     * share the same last name and postcode. The last name is compared
     * case-insensitively with runs of whitespace collapsed to a single space (and
     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
     * absent postcodes count as equal). Owners in the same household resolve to the same
     * {@link #computeHouseholdId() household identifier}.
     *
     * @param other the owner to compare against
     * @return {@code true} if both owners share a household
     */
    public boolean sameHouseholdAs(Owner other) {
        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
            && Objects.equals(this.postcode, other.postcode);
    }

    /**
     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
     * trim, collapse internal runs of whitespace to a single space and lower-case.
     */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /**
     * Reduce an address to its canonical stored form: trim and collapse runs of
     * whitespace to a single space, upper-case, and expand common abbreviations
     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
     * they appear as whole words. The result is what is stored, returned and used
     * for every household comparison; it is idempotent, so re-normalising an
     * already-normalised address leaves it unchanged.
     *
     * @param value the raw address (may be {@code null})
     * @return the normalised address, or the empty string if {@code value} is
     *         {@code null} or blank
     */
    public static String normalizeAddress(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        for (int i = 0; i < tokens.length; i++) {
            tokens[i] = switch (tokens[i]) {
                case "ST" -> "STREET";
                case "RD" -> "ROAD";
                case "AVE" -> "AVENUE";
                default -> tokens[i];
            };
        }
        return String.join(" ", tokens);
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

    protected void setPetsInternal(Set<Pet> pets) {
        this.pets = pets;
    }

    public List<Pet> getPets() {
        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(sortedPets);
    }

    public void setPets(List<Pet> pets) {
        this.pets = new HashSet<>(pets);
    }

    public void addPet(Pet pet) {
        getPetsInternal().add(pet);
        pet.setOwner(this);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (Pet pet : getPetsInternal()) {
            if (!ignoreNew || !pet.isNew()) {
                String compName = pet.getName();
                compName = compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    public Pet getPet(Integer petId) {
        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
    }

    @Override
    public String toString() {
        return new ToStringCreator(this)

            .append("id", this.getId())
            .append("new", this.isNew())
            .append("lastName", this.getLastName())
            .append("firstName", this.getFirstName())
            .append("address", this.address)
            .append("city", this.city)
            .append("telephone", this.telephone)
            .toString();
    }
}

